# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, J, B, V = "Hélène", "Julien", "Bastide", "Victor"
D = [
(None, "Mardi 1er juin, 7 h 20. La cuisine est silencieuse. Pas de camion devant la porte. Hélène regarde l'horloge, le téléphone à la main. Julien entre, essoufflé.", "6월 1일 화요일 오전 7시 20분. 주방이 조용하다. 문 앞에 트럭이 없다. 엘렌은 전화기를 손에 쥐고 시계를 본다. 쥘리앵이 숨을 헐떡이며 들어온다."),
(J, "Hélène, t'as vu les infos ? Les routiers bloquent tout depuis hier soir.", "엘렌, 뉴스 봤어? 트럭 기사들이 어제저녁부터 다 막고 있대."),
(H, "J'ai vu. Rungis est bloqué. Et mon livreur de poisson vient de m'appeler.", "봤어. 렁지스도 막혔대. 그리고 생선 납품업자가 방금 전화했어."),
(J, "Il ne vient pas ?", "안 온대?"),
(H, "Il ne vient pas. Ni le poisson, ni la crème, ni le beurre de Rungis.", "안 온대. 생선도, 크림도, 렁지스 버터도 없어."),
(J, "Putain. Un jour de rentrée de mai, avec quarante couverts réservés.", "젠장. 하필 5월 끝물에 예약이 40명인 날에."),
(H, "On ne panique pas. Réfléchissons. Qu'est-ce qu'il nous reste en réserve ?", "당황하지 말자. 생각해 보자. 비축분에 뭐가 남았지?"),
(J, "Des pommes de terre, des oignons, des œufs, un peu de farine, du vin.", "감자, 양파, 달걀, 밀가루 조금, 와인."),
(H, "Pas de poisson, pas de crème, quatre plaquettes de beurre. C'est maigre.", "생선도 크림도 없고 버터는 네 덩이. 빈약하네."),
(J, "On appelle Bastide ? Il vit à la campagne, lui, il n'est pas coincé sur l'autoroute.", "바스티드한테 전화할까? 시골에 사니까 고속도로에 갇히진 않았을 거야."),
(H, "J'y pense. Passe-moi mon portable, il est sur le plan de travail.", "나도 그 생각 중이야. 작업대에 있는 내 휴대폰 좀 줘."),
(None, "Elle compose le numéro. Ça sonne trois fois. Bastide répond, la voix joyeuse malgré le bruit de moteur.", "엘렌이 번호를 누른다. 세 번 울린다. 바스티드가 엔진 소리 속에서도 명랑한 목소리로 받는다."),
(B, "Allô, Hélène ? J'allais justement t'appeler. Tu as vu le grabuge ?", "여보세요, 엘렌? 마침 전화하려던 참이었어. 난리 난 거 봤지?"),
(H, "Je l'ai vu. Je n'ai rien reçu ce matin. Tu es où ?", "봤어요. 오늘 아침 아무것도 못 받았어요. 어디예요?"),
(B, "Sur la route de Gisors, par les petits chemins. J'ai le camion plein, ou presque.", "지조르 가는 길인데 샛길로 가고 있어. 트럭은 꽉 차거나 거의 꽉 찼어."),
(H, "Plein de quoi ? Dis-moi tout.", "뭐로 찼는데요? 다 말해 주세요."),
(B, "Des pommes de terre nouvelles, des asperges blanches, des œufs, du veau, du beurre fermier.", "햇감자, 화이트 아스파라거스, 달걀, 송아지고기, 농장 버터."),
(H, "Du beurre fermier ? Bastide, je te dois une médaille.", "농장 버터요? 바스티드, 메달이라도 드려야겠네요."),
(B, "Garde ta médaille. Garde ta table pour moi à midi, on s'est compris ?", "메달은 됐고. 점심때 내 자리나 하나 남겨 둬, 알겠지?"),
(H, "Marché conclu. Tu arrives quand ?", "좋아요. 언제 도착해요?"),
(B, "Avec ces barrages, comptez deux bonnes heures. Je vous garde du café chaud sur la route.", "저 바리케이드 때문에 두 시간은 걸려. 길에서 마실 따뜻한 커피는 챙겨 놨어."),
(H, "Fais attention. Je préfère te savoir en retard qu'en danger.", "조심해요. 위험한 것보다는 늦는 게 나아요."),
(None, "Elle raccroche. Julien l'observe, un peu rassuré.", "엘렌이 전화를 끊는다. 쥘리앵이 조금 안심한 얼굴로 그녀를 바라본다."),
(J, "Alors ? Le veau, les asperges, les œufs. On a de quoi faire un menu.", "그래서? 송아지, 아스파라거스, 달걀. 메뉴는 짤 수 있겠는데."),
(H, "On a de quoi tenir le midi. Mais sans crème ni poisson, mon menu s'écroule.", "점심은 버틸 수 있어. 하지만 크림이랑 생선 없이는 메뉴가 무너져."),
(J, "On remplace le cabillaud par un autre plat. Une poule au pot, par exemple ?", "대구 대신 다른 요리를 넣자. 예를 들어 닭 요리는?"),
(H, "On n'a pas de poule. Mais Bastide a des poulets fermiers, j'en ai vu la semaine dernière.", "닭이 없잖아. 하지만 바스티드한테 방사 닭이 있어, 지난주에 봤어."),
(J, "Alors on lui commande des poulets en plus. Je le rappelle ?", "그럼 닭도 더 주문하자. 내가 다시 전화할까?"),
(H, "Non, laisse-le conduire. On verra à son arrivée.", "아니, 운전하게 두자. 도착하면 보자."),
(None, "8 h 40. Quelqu'un frappe à la porte de service. C'est Victor, un grand carton dans les bras.", "오전 8시 40분. 누군가 뒷문을 두드린다. 빅토르가 큰 상자를 안고 서 있다."),
(V, "Bonjour, vous deux. J'ai l'air d'un déménageur ?", "안녕, 두 사람. 내가 이삿짐센터 직원처럼 보여?"),
(H, "Victor ? Qu'est-ce que tu fais ici à cette heure ?", "빅토르? 이 시간에 여긴 무슨 일이야?"),
(V, "J'ai vu ton livreur repartir à vide. Les routiers ont aussi coincé le mien.", "네 납품업자가 빈 차로 돌아가는 걸 봤어. 우리 쪽 업자도 막혔고."),
(H, "Et alors ? Tu viens te plaindre ?", "그래서? 하소연하러 왔어?"),
(V, "Non. Je viens t'aider. J'ai une chambre froide pleine depuis hier : beurre, crème, filets de cabillaud.", "아니. 도와주러 왔어. 어제부터 냉장고가 가득 차 있어. 버터, 크림, 대구 필레."),
(J, "Pourquoi tu en as autant ?", "왜 그렇게 많이 있어?"),
(V, "J'ai fait un gros achat chez un grossiste hier, pour le week-end. Une chance.", "어제 도매상에서 주말용으로 대량 구매를 했거든. 운이 좋았지."),
(H, "Victor, je ne peux pas accepter. C'est ton stock.", "빅토르, 받을 수 없어. 그건 네 재고잖아."),
(V, "Hélène, ne fais pas ta fière. Dix kilos de beurre ne se mangent pas seul.", "엘렌, 자존심 부리지 마. 버터 10킬로는 혼자 못 먹어."),
(J, "Il a raison. Un voisin qui aide, ça ne se refuse pas.", "그 말이 맞아. 도와주는 이웃은 거절하는 게 아니야."),
(H, "Mais je ne veux pas te mettre en difficulté. Et ce midi, tu auras besoin de tout.", "하지만 너를 곤란하게 만들고 싶지 않아. 오늘 점심에는 네게도 다 필요할 텐데."),
(V, "Je garde la moitié pour moi. Je te laisse l'autre. On partage, voilà tout.", "절반은 내가 갖고 나머지는 너한테 줄게. 나누자, 그게 다야."),
(H, "D'accord. Mais je te rends la pareille. J'ai du fond de veau maison et ma farine de blé noir.", "알겠어. 대신 나도 보답할게. 직접 만든 송아지 육수랑 메밀가루가 있어."),
(V, "Ton fond de veau ? Il paraît que même le critique en parle.", "네 송아지 육수? 비평가도 그 얘기를 한다던데."),
(H, "On échange, alors. Quatre litres de fond contre ton beurre et ta crème.", "그럼 교환하자. 육수 4리터를 네 버터랑 크림이랑."),
(V, "Quatre litres de fond contre dix kilos de beurre ? Je gagne au change.", "육수 4리터와 버터 10킬로? 내가 이득이네."),
(J, "Tu gagnes ? Personne ne gagne. On fait contre mauvaise fortune bon cœur.", "네가 이득이라고? 아무도 이득 안 봐. 불운에도 웃으며 맞서는 거지."),
(V, "Bien dit. À la guerre comme à la guerre.", "맞는 말이야. 전시에는 전시답게."),
(None, "Victor pose le carton sur la table en inox. Hélène vérifie les filets, le beurre, la crème. Tout est parfait.", "빅토르가 스테인리스 탁자에 상자를 내려놓는다. 엘렌이 필레와 버터, 크림을 살핀다. 모두 완벽하다."),
(H, "Ils sont magnifiques, tes filets. Tu les as eus où ?", "필레가 정말 훌륭하네. 어디서 구했어?"),
(V, "Un petit pêcheur de Boulogne. Un copain. Je te donnerai son nom.", "불로뉴의 작은 어부야. 친구지. 이름 알려 줄게."),
(H, "Tu me donnerais son nom ? Alors c'est vraiment de la confiance.", "그 이름을 알려 준다고? 정말 신뢰의 표시네."),
(V, "Le métier est assez dur. Si on s'entraide, on tient plus longtemps.", "이 일은 충분히 힘들어. 서로 도우면 더 오래 버틸 수 있잖아."),
(J, "Victor, tu veux un café ? On vient de lancer la machine.", "빅토르, 커피 마실래? 방금 기계 켰어."),
(V, "Je dis pas non. Mais je file ouvrir ma cuisine après, j'ai vingt couverts.", "마다하진 않지. 그래도 이거 마시고 바로 내 주방 열러 가야 해. 20자리 예약이야."),
(None, "9 h 30. Un klaxon dans la rue. Le camion de Bastide, couvert de poussière, se gare en double file.", "오전 9시 30분. 거리에서 경적 소리. 먼지를 뒤집어쓴 바스티드의 트럭이 이중 주차한다."),
(B, "Voilà la cavalerie ! Dix barrages, trois détours, deux chiens perdus.", "기병대 도착이다! 바리케이드 열 개, 우회로 세 번, 길 잃은 개 두 마리."),
(H, "Bastide, tu es magnifique. Entre vite, prends un café.", "바스티드, 정말 대단해요. 어서 들어와서 커피 마셔요."),
(B, "Je commence par décharger. Ensuite, le café, et peut-être un croissant.", "먼저 짐부터 내리고. 그다음에 커피, 크루아상도 있으면 좋고."),
(J, "Je t'aide. Passe-moi la caisse d'asperges, elle a l'air lourde.", "도와줄게요. 아스파라거스 상자 줘요, 무거워 보이네."),
(B, "Pas si vite, Julien ! Les asperges se portent comme des bébés.", "서두르지 마, 쥘리앵! 아스파라거스는 아기처럼 다뤄야 해."),
(V, "Tiens, Bastide. Vous livrez aussi les voisins, maintenant ?", "어, 바스티드 씨. 이제 이웃에게도 배달하세요?"),
(B, "Victor ! Si tu me paies comptant, je livre même ta mère.", "빅토르! 현금으로 주면 네 어머니 댁까지도 배달해 주지."),
(V, "Je prends deux kilos de petits pois et dix asperges pour ce midi.", "오늘 점심용으로 완두콩 2킬로랑 아스파라거스 10개 주세요."),
(B, "Tu en auras vingt. C'est la solidarité des petits.", "스무 개 줄게. 작은 가게들의 연대잖아."),
(H, "Bastide, je veux aussi quatre poulets fermiers, pour remplacer le cabillaud.", "바스티드, 대구 대신 방사 닭도 네 마리 필요해요."),
(B, "Les poulets, je les ai dans la remorque. Trois, pas quatre.", "닭은 짐칸에 있어. 네 마리가 아니라 세 마리야."),
(H, "Trois ça ira. On fera aussi une omelette aux herbes et un velouté d'asperges.", "세 마리면 돼요. 허브 오믈렛이랑 아스파라거스 벨루테도 하죠."),
(J, "Et on garde la blanquette. Le veau de Bastide, c'est la meilleure assurance.", "블랑케트도 그대로 가자. 바스티드 송아지는 최고의 보험이야."),
(B, "Flatteur ! Tu as gagné une part de tarte aux fraises dans la remorque.", "아부쟁이! 짐칸에 딸기 타르트 한 조각 챙겨 놨으니 받아 가."),
(J, "Une tarte aux fraises ? Bastide, je t'adore.", "딸기 타르트? 바스티드, 사랑해요."),
(H, "Bon, on s'organise. Julien, tu réécris l'ardoise. Menu de crise, mais élégant.", "자, 정리하자. 쥘리앵, 칠판 다시 써. 위기 메뉴지만 우아하게."),
(J, "« Menu de saison, selon les arrivages. » Ça sonne mieux que « grève ».", "« 입하 상황에 따른 제철 메뉴. » 이게 « 파업 » 보다 듣기 좋네."),
(V, "Ça, c'est un coup de génie. J'adore l'idée.", "천재적인데. 아이디어가 마음에 들어."),
(H, "Victor, on fait quoi si ça dure demain ?", "빅토르, 내일도 계속되면 어떻게 해?"),
(V, "On s'organise. Un achat groupé. On commande ensemble, on divise, on tient.", "함께 준비하자. 공동 구매야. 같이 주문하고 나눠서 버티는 거지."),
(B, "Et moi, je ramène des collègues. Un maraîcher de Pontoise et une fermière de l'Oise.", "나는 동료들을 데려올게. 퐁투아즈 채소 농가와 우아즈 농장 아주머니."),
(H, "Tu ferais ça ? Ils viendraient jusqu'ici ?", "그렇게 해 줄 거예요? 여기까지 와 줄까요?"),
(B, "Pourquoi pas ? Ils rêvent de vendre en direct à Paris.", "안 될 게 뭐 있어? 다들 파리에 직접 팔고 싶어 하는데."),
(J, "Ça fait un petit marché de crise. Quelle idée géniale.", "작은 위기 장터가 되겠네. 정말 좋은 생각이야."),
(None, "11 h 45. La cuisine bourdonne. Hélène coupe des asperges, Julien passe l'ardoise à la craie. Victor, au pas de course, repart vers son restaurant.", "오전 11시 45분. 주방이 분주하다. 엘렌은 아스파라거스를 썰고, 쥘리앵은 칠판에 분필로 글을 쓴다. 빅토르가 뛰다시피 자기 가게로 돌아간다."),
(V, "À tout à l'heure. Et bon courage, les amis.", "나중에 봐. 모두 힘내."),
(H, "Merci, Victor. Vraiment. Je n'oublierai pas.", "고마워, 빅토르. 정말로. 잊지 않을게."),
(V, "Arrête. Ce qui compte, c'est que la rue Saint-Maur mange bien aujourd'hui.", "그만해. 중요한 건 오늘 생모르 가 사람들이 잘 먹는 거야."),
(J, "Hélène, les premiers clients arrivent. Ils regardent l'ardoise avec méfiance.", "엘렌, 첫 손님들이 오고 있어. 칠판을 미심쩍게 보고 있어."),
(H, "Va leur parler. Explique sans dramatiser.", "가서 말씀드려. 과장하지 말고 설명해."),
(J, "Bonjour, messieurs-dames. Je vous explique : à cause de la grève, certains plats changent.", "안녕하세요, 손님 여러분. 설명드리자면, 파업 때문에 일부 요리가 바뀌었습니다."),
(J, "Mais tout est frais, tout est fermier. Vous allez même gagner au change.", "하지만 전부 신선하고 농장 직송입니다. 오히려 득을 보실 거예요."),
(J, "Je vous recommande le velouté d'asperges et le poulet rôti au beurre fermier.", "아스파라거스 벨루테와 농장 버터로 구운 닭요리를 추천드립니다."),
(B, "Julien, tu fais le service ? Je peux m'installer au comptoir ?", "쥘리앵, 서비스 중이지? 나 카운터에 앉아도 돼?"),
(J, "Évidemment, Bastide. Ta place est réservée, comme promis. Un verre de Brouilly ?", "물론이죠, 바스티드. 약속대로 자리 잡아 놨어요. 브루이 한 잔 할래요?"),
(B, "Un petit verre, avec plaisir. J'ai la gorge sèche, à force de klaxonner.", "한 잔만 기꺼이. 경적을 울려 대서 목이 말라."),
(None, "13 h 30. La salle est pleine. Les assiettes sortent sans arrêt. Mme Vasseur, installée à la sept, goûte le velouté.", "오후 1시 30분. 홀이 가득 찼다. 접시가 쉼 없이 나간다. 7번 자리의 바쉐 부인이 벨루테를 맛본다."),
(J, "Madame Vasseur, tout va bien ? Le velouté vous plaît ?", "바쉐 부인, 괜찮으세요? 벨루테 마음에 드세요?"),
(H, "Je l'entends d'ici. Elle a dit « pas mal », ce qui veut dire « excellent ».", "여기서도 들려. « 나쁘지 않네 » 라고 하셨어, 그건 « 최고네 » 라는 뜻이야."),
(J, "Elle m'a même demandé si on pouvait faire grève plus souvent.", "심지어 파업을 더 자주 하면 안 되냐고 물으시더라."),
(H, "Elle plaisante. Elle plaisante, hein ?", "농담하신 거지. 농담이신 거지?"),
(B, "Avec Mme Vasseur, on ne sait jamais. Mais elle a de l'humour, la mère.", "바쉐 부인은 알 수가 없지. 하지만 유머 있는 분이야."),
(H, "Je te l'accorde. Bastide, tu restes jusqu'à la fin du service ?", "인정해요. 바스티드, 서비스 끝날 때까지 있을 거예요?"),
(B, "Jusqu'au café, et puis je repars chercher la deuxième tournée.", "커피 마실 때까지만 있고 나서 두 번째 배달 가지러 다시 가야지."),
(H, "Tu repars ? Avec la grève, ce n'est pas raisonnable.", "또 가요? 파업 중에 그건 무리예요."),
(B, "Ma petite Hélène, on n'a pas fait vingt ans de route pour s'arrêter à un barrage.", "엘렌, 우리가 20년 길을 달려온 건 바리케이드 하나 앞에서 멈추려는 게 아니야."),
(J, "C'est ça, l'esprit. Bastide, tu es notre héros du jour.", "그게 바로 그 정신이죠. 바스티드는 오늘의 영웅이에요."),
(B, "Un héros avec un tablier plein de poussière, c'est ça ?", "먼지투성이 앞치마를 두른 영웅이라니?"),
(V, "Excusez-moi de vous déranger. Je repasse entre deux services.", "방해해서 미안. 서비스 사이에 잠깐 들렀어."),
(H, "Victor ? Déjà ? Ta cuisine ?", "빅토르? 벌써? 주방은?"),
(V, "Mon second a pris le relais pour dix minutes. Je voulais voir comment ça se passait.", "부주방장이 10분만 맡아 줬어. 여기 상황이 어떤지 보고 싶었거든."),
(H, "Salle pleine, plats prêts, clients rassurés. Et ton beurre est dans le velouté.", "홀은 가득 차고, 요리는 나가고, 손님은 안심했어. 네 버터는 벨루테에 들어갔고."),
(V, "Alors c'est une belle journée. Je file. On s'appelle ce soir ?", "그럼 좋은 하루네. 가 볼게. 오늘 저녁에 전화할까?"),
(H, "On s'appelle. On fait le point sur l'achat groupé.", "그래. 공동 구매 얘기 정리하자."),
(None, "16 h. Le service est terminé. Dans la cuisine, Hélène, Julien et Bastide boivent un dernier café. La fatigue se mêle au rire.", "오후 4시. 서비스가 끝났다. 주방에서 엘렌, 쥘리앵, 바스티드가 마지막 커피를 마신다. 피로와 웃음이 섞여 있다."),
(J, "Quarante et un couverts. Aucune plainte. Un petit miracle.", "41명. 불만은 없었어. 작은 기적이야."),
(H, "Ce n'est pas un miracle. C'est de la solidarité, et un peu de chance.", "기적이 아니야. 연대와 약간의 운이지."),
(B, "Et du beurre fermier. Sans beurre, pas de cuisine, pas de miracle.", "그리고 농장 버터. 버터가 없으면 요리도, 기적도 없지."),
(H, "Bastide, merci. Tu as sauvé le midi. Je te dois combien pour cette livraison spéciale ?", "바스티드, 고마워요. 오늘 점심을 구해 줬어요. 이번 특별 배달은 얼마를 드려야 해요?"),
(B, "Le prix normal. Pas un centime de plus. Les amis, on ne les fait pas payer le danger.", "정상 가격이야. 한 푼도 더 받지 않아. 친구한테 위험수당을 받진 않지."),
(H, "Alors le prix normal, et un dessert gratuit pour toute ta famille, quand tu veux.", "그럼 정상 가격에, 가족 모두에게 디저트를 공짜로 드릴게요. 원할 때 언제든지."),
(B, "Marché conclu ! Mais je demande la tarte Tatin, pas la mousse.", "좋아! 단, 무스 말고 타르트 타탱으로 부탁해."),
(J, "Demain, la grève continue peut-être. On s'organise comment ?", "내일도 파업이 계속될 수 있어. 어떻게 준비하지?"),
(H, "On reste en alerte. Julien, appelle Victor. Bastide, tu reviens à l'aube avec tes collègues.", "비상 대기야. 쥘리앵, 빅토르한테 전화해. 바스티드, 새벽에 동료들과 다시 와 줘요."),
(B, "À six heures, devant la porte de service. Je prends le café, vous prenez les cageots.", "6시에 뒷문 앞에서 봐. 나는 커피를 받고, 너희는 상자를 받는 거지."),
(H, "Ça marche. Une belle histoire à raconter à Lucien, quand il ira mieux.", "좋아요. 아빠가 좀 나아지면 들려드릴 멋진 이야기가 생겼네."),
]

